INSERT INTO `openalex_works` VALUES ('W1541215243','https://openalex.org/W1541215243',NULL,'Teachers’ Competence in Using Cooperative Learning Strategy in Teaching Economics in Secondary Schools in Anambra State Nigeria','Teachers’ Competence in Using Cooperative Learning Strategy in Teaching Economics in Secondary Schools in Anambra State Nigeria',2014,'2014-01-01','article',NULL,'[{\"name\":\"Njideka Dorathy Eneogu\",\"id\":\"A5053838368\",\"orcid\":null,\"institutions\":[],\"is_corresponding\":false},{\"name\":\"Jovita Chinelo Ejimonye\",\"id\":\"A5077360199\",\"orcid\":\"https:\\/\\/orcid.org\\/0009-0008-7818-6710\",\"institutions\":[],\"is_corresponding\":false}]',NULL,NULL,NULL,'This study investigated the Economics teachers’ competence in using cooperative learning strategy in teaching economics in secondary schools in Anambra State, Nigeria. Out of the six education zones in Anambra state namely; Onitsha, Aguata, Nnewi, Otuocha, Ogidi and Awka, three  education zones which are Awka, Aguata and Ogidi were randomly selected for the study.150 Economics teachers’ in the three zones were selected using proportionate stratified random sampling for the study. Four research questions and two hypotheses guided the study. The design for the study was a descriptive survey and a questionnaire titled Economics teachers’ competence in the use of cooperative learning, structured by the researchers was used to gather data from the respondent.  The data collected were analyzed using mean and standard deviation while the hypotheses were tested using analysis of variance (ANOVA). Result from the study show that the Economics teachers’ are competent but not very competent in planning and preparing students for, conducting and assessing cooperative learning tasks considering the standard deviations that are far from the mean. The findings from the test of hypotheses revealed that teachers qualification and years of teaching experience are significant factors in the competence possessed by economics teachers in using cooperative learning strategy. Based on the findings, recommendations were made which include that government should re-train teacher’s on cooperative learning strategy through seminars and workshops and that Economics teachers should always employ learner centered approach to teaching like; cooperative learning strategy so that students will become accountable for their learning as they all make contributions to the learning process and thereby make the study of economics more interesting. Key words: Cooperative learning, Teacher Competence, Years of teaching experiences, Economics.',0,'closed',NULL,NULL,0,'[{\"name\":\"Innovative Teaching and Learning Methods\",\"subfield\":\"Developmental and Educational Psychology\",\"field\":\"Psychology\",\"domain\":\"Social Sciences\"},{\"name\":\"Innovative Teaching Methodologies in Social Sciences\",\"subfield\":\"Education\",\"field\":\"Social Sciences\",\"domain\":\"Social Sciences\"},{\"name\":\"Collaborative Teaching and Inclusion\",\"subfield\":\"Education\",\"field\":\"Social Sciences\",\"domain\":\"Social Sciences\"}]','[{\"name\":\"Respondent\",\"score\":0.77,\"level\":2},{\"name\":\"Mathematics education\",\"score\":0.63,\"level\":1},{\"name\":\"Competence (human resources)\",\"score\":0.62,\"level\":2},{\"name\":\"Descriptive statistics\",\"score\":0.57,\"level\":2},{\"name\":\"Stratified sampling\",\"score\":0.56,\"level\":2},{\"name\":\"Local government area\",\"score\":0.53,\"level\":3},{\"name\":\"Economics education\",\"score\":0.53,\"level\":3},{\"name\":\"Cooperative learning\",\"score\":0.47,\"level\":3},{\"name\":\"Psychology\",\"score\":0.47,\"level\":0},{\"name\":\"Survey methodology\",\"score\":0.44,\"level\":2},{\"name\":\"Teaching method\",\"score\":0.4,\"level\":2},{\"name\":\"Local government\",\"score\":0.27,\"level\":2},{\"name\":\"Primary education\",\"score\":0.21,\"level\":2},{\"name\":\"Mathematics\",\"score\":0.14,\"level\":0},{\"name\":\"Geography\",\"